  const fin = (u0, u1, tipU, tipV, baseV, col) => { const steps = Math.ceil(Math.abs(tipV - baseV) * len); for (let s = 0; s <= steps; s++) { const k = s / (steps || 1), a = H.lerp(u0, tipU, k * k * 0.6 + k * 0.4), b = H.lerp(u1, tipU, Math.pow(k, 0.7)), v = H.lerp(baseV, tipV, k); for (let u = Math.min(a, b) - 1 / len; u <= Math.max(a, b) + 1 / len; u += 0.5 / len) { put(px(u), cl(u) + v * len, DC.K); } for (let u = Math.min(a, b); u <= Math.max(a, b); u += 0.5 / len) { if (s < steps) put(px(u), cl(u) + v * len, col); } } };
