const titleCard = (n, name, t0) => { chromeBG(n * 3 + 1, '#10082e', '#43206a'); const k = Math.floor(pr(t0 - 0.1, t0 + 0.25) * 6) / 6, y = Math.round(70 - (1 - k) * 40); const w = Math.max(name.length * 16 + 28, 180); win(160 - w / 2, y, w, 44); ctext('CHAPTER ' + n, 160, y + 7, cyan); ctext(name, 160, y + 22, white, ink, 16); for (let i = 0; i < 5; i++) { const a = i * 1.25 + T * 2; put(160 + Math.cos(a) * (w / 2 + 8), y + 22 + Math.sin(a) * 28, gold); } };
