// ---------- timeline ----------
SCENES.sort((a, b) => a.t0 - b.t0);
const clearBuf = () => { for (let i = 3; i < buf.length; i += 4) buf[i] = 255; };
const lc = document.createElement('canvas'); lc.width = LW; lc.height = LH; const lx = lc.getContext('2d');
function frame(ctx, W, H_, tt) {
  T = Math.floor(tt * 12) / 12;
  let idx = 0; for (let i = 0; i < SCENES.length; i++) if (T >= SCENES[i].t0) idx = i;
  const s = SCENES[idx]; buf.fill(0); clearBuf(); s.fn();
  if (s.ch) hdr(s.ch);
  const d = T - s.t0, nxt = SCENES[idx + 1], left = nxt ? nxt.t0 - T : 99;
  const trn = (type, k) => { // k: 0 = full effect, 1 = clear
    if (type === 'mosaic') { const n = Math.round(1 + (1 - k) * 15); if (n > 1) for (let by = 0; by < LH; by += n) for (let bx = 0; bx < LW; bx += n) { const sx = Math.min(LW - 1, bx + (n >> 1)), sy = Math.min(LH - 1, by + (n >> 1)), si = (sy * LW + sx) * 4; for (let y = by; y < Math.min(LH, by + n); y++) for (let x = bx; x < Math.min(LW, bx + n); x++) { const i = (y * LW + x) * 4; buf[i] = buf[si]; buf[i + 1] = buf[si + 1]; buf[i + 2] = buf[si + 2]; } } }
    else if (type === 'swirl') { const w = 1 - k, src = buf.slice(); for (let y = 0; y < LH; y++) { const off = Math.round(Math.sin(y * .25 + T * 30) * w * 40); for (let x = 0; x < LW; x++) { const sx = ((x + off) % LW + LW) % LW, si = (y * LW + sx) * 4, i = (y * LW + x) * 4; for (let c = 0; c < 3; c++) buf[i + c] = src[si + c] + (255 - src[si + c]) * w * .6; } } }
    else if (type === 'iris') { const R = Math.round(k * 200); for (let y = 0; y < LH; y++) for (let x = 0; x < LW; x++) if ((x - 160) ** 2 + (y - 90) ** 2 > R * R) { const i = (y * LW + x) * 4; buf[i] = buf[i + 1] = buf[i + 2] = 0; } }
    else if (type === 'fade') { const v = Math.floor(k * 16) / 16; for (let i = 0; i < buf.length; i += 4) { buf[i] *= v; buf[i + 1] *= v; buf[i + 2] *= v; } }
  };
  if (d < 0.25 && s.tr !== 'cut') trn(s.tr, H.clamp(d / 0.25));
  else if (left < 0.17 && nxt && nxt.tr !== 'cut') trn(nxt.tr, H.clamp(left / 0.17));
  if (T > DUR - 0.5) trn('fade', H.clamp((DUR - T) / 0.5));
  lx.putImageData(new ImageData(buf, LW, LH), 0, 0);
  ctx.save(); ctx.imageSmoothingEnabled = false; ctx.drawImage(lc, 0, 0, W, H_); ctx.restore();
}
